import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

function freezeTree(value) {
  if (value && typeof value === 'object') {
    for (const key of Reflect.ownKeys(value)) freezeTree(value[key]);
    Object.freeze(value);
  }
  return value;
}

if (process.argv[2] === 'deep') {
  const defaults = freezeTree({
    server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: { path: '/old', format: 'pem' } } },
    flags: { a: true, b: false }, untouched: 12,
  });
  const overrides = freezeTree({
    server: { port: 9090, tls: { cert: { path: '/new' }, version: 3 } },
    flags: {}, added: { nested: { value: 42 } },
  });
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: '/new', format: 'pem' }, version: 3 } },
    flags: { a: true, b: false }, untouched: 12, added: { nested: { value: 42 } },
  });
  assert.equal(defaults.server.port, 8080);
  assert.deepEqual(overrides.flags, {});

  // Mixed branches must recurse only for object/object pairs.
  assert.deepEqual(mergeConfig(
    freezeTree({ section: { keep: 'yes', tags: ['a', 'b'], disabled: { x: 1 }, scalar: 4, nested: { keep: 7, value: 1 } } }),
    freezeTree({ section: { tags: ['c'], disabled: null, scalar: { x: 2 }, nested: { value: undefined } } }),
  ), { section: { keep: 'yes', tags: ['c'], disabled: null, scalar: { x: 2 }, nested: { keep: 7, value: undefined } } });

  // No fixed recursion cutoff; each level has siblings that must survive.
  for (const depth of [1, 2, 5, 17, 80]) {
    let a = { keep: 'leaf', replace: 'old' };
    let b = { replace: 'new', added: true };
    let expected = { keep: 'leaf', replace: 'new', added: true };
    for (let i = 0; i < depth; i++) {
      a = { child: a, retained: i, changed: 'old' };
      b = { child: b, changed: 'new' };
      expected = { child: expected, retained: i, changed: 'new' };
    }
    freezeTree(a); freezeTree(b);
    assert.deepEqual(mergeConfig(a, b), expected);
  }

  // Null-prototype dictionaries are plain objects too; do not prescribe
  // the prototype of the new result, only its keys and values.
  const a = Object.assign(Object.create(null), { keep: 1, child: { old: 2 } });
  const b = Object.assign(Object.create(null), { child: { added: 3 } });
  const result = mergeConfig({ dictionary: a }, { dictionary: b });
  assert.deepEqual(Object.keys(result.dictionary).sort(), ['child', 'keep']);
  assert.equal(result.dictionary.keep, 1);
  assert.deepEqual(result.dictionary.child, { old: 2, added: 3 });
} else if (process.argv[2] === 'regression') {
  assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), {
    level: 'debug', color: true, file: 'app.log',
  });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ x: 1 }, {}), { x: 1 });
  assert.deepEqual(mergeConfig({}, { x: 1 }), { x: 1 });

  class Box { constructor() { this.value = 2; } }
  const values = [null, undefined, 'string', 0, false, ['c'], new Date(0), /x/, new Box(), () => 1];
  for (const replacement of values) {
    const defaults = freezeTree({ item: { retained: true }, other: 9 });
    const overrides = Object.freeze({ item: replacement });
    const result = mergeConfig(defaults, overrides);
    assert.deepEqual(result, { item: replacement, other: 9 });
    assert.strictEqual(result.item, replacement);
    assert.deepEqual(defaults, { item: { retained: true }, other: 9 });
    assert.strictEqual(overrides.item, replacement);
  }
  for (const original of values) {
    const replacement = freezeTree({ added: 4 });
    assert.deepEqual(mergeConfig({ item: original }, { item: replacement }), { item: { added: 4 } });
  }
  const defaults = { a: 1, untouched: { b: 2 } };
  const overrides = { a: 2 };
  const result = mergeConfig(defaults, overrides);
  assert.notStrictEqual(result, defaults);
  assert.notStrictEqual(result, overrides);
  assert.deepEqual(defaults, { a: 1, untouched: { b: 2 } });
  assert.deepEqual(overrides, { a: 2 });
} else {
  throw new Error('Specify deep or regression');
}
